public class AndroidPermissionHandler : MonoBehaviour
{
    private Action<Dictionary<string, bool>> onPermissionsResultCallback;

    public void RequestPermissions(string[] permissions, Action<Dictionary<string, bool>> callback)
    {
        onPermissionsResultCallback = callback;
#if UNITY_ANDROID && !UNITY_EDITOR
        List<string> permissionsToRequest = new List<string>();
        foreach (var p in permissions)
        {
            if (!Permission.HasUserAuthorizedPermission(p))
            {
                permissionsToRequest.Add(p);
            }
        }

        if (permissionsToRequest.Count > 0)
        {
            Permission.RequestUserPermissions(permissionsToRequest.ToArray(), new PermissionCallbacks());
        }
        else
        {
            // Nếu tất cả quyền đã được cấp, gọi callback ngay lập tức
            Dictionary<string, bool> results = new Dictionary<string, bool>();
            foreach (var p in permissions)
            {
                results[p] = true;
            }
            onPermissionsResultCallback?.Invoke(results);
        }
#else
        // Trên Editor hoặc nền tảng khác, giả sử tất cả quyền đều được cấp
        Dictionary<string, bool> results = new Dictionary<string, bool>();
        foreach (var p in permissions)
        {
            results[p] = true;
        }
        callback?.Invoke(results);
#endif
    }

    // Lớp nội bộ để xử lý callbacks
    private class PermissionCallbacks : IPermissionRequestCallbacks
    {
        // Tạm thời, chúng ta sẽ cần một cách để truy cập lại instance của AndroidPermissionHandler
        // Một cách đơn giản là dùng Singleton hoặc một biến static.
        // Ở đây, chúng ta sẽ giả định AndroidPermissionHandler là một Singleton để đơn giản.
        // private static AndroidPermissionHandler Instance => FindObjectOfType<AndroidPermissionHandler>();

        public void OnPermissionGranted(string permissionName)
        {
            // Cần một cơ chế để gọi lại callback với kết quả
            Debug.Log($"Permission {permissionName} granted.");
        }

        public void OnPermissionDenied(string permissionName)
        {
            Debug.LogWarning($"Permission {permissionName} denied.");
        }

        public void OnPermissionDeniedAndDontAskAgain(string permissionName)
        {
            Debug.LogWarning($"Permission {permissionName} denied and won't be asked again.");
        }
    }
}

