using UnityEngine;

public class NativeUIController : MonoBehaviour
{
    #if UNITY_ANDROID && !UNITY_EDITOR
    private AndroidJavaObject currentActivity;
    #endif

    void Start()
    {
        #if UNITY_ANDROID && !UNITY_EDITOR
        // Lấy context activity hiện tại của Unity
        using (var unityPlayer = new AndroidJavaClass("com.unity3d.player.UnityPlayer"))
        {
            currentActivity = unityPlayer.GetStatic<AndroidJavaObject>("currentActivity");
        }
        #endif
    }

    /// <summary>
    /// Hiển thị một thông báo Toast ngắn của Android.
    /// </summary>
    public void ShowToast(string message)
    {
        #if UNITY_ANDROID && !UNITY_EDITOR
        currentActivity.Call("runOnUiThread", new AndroidJavaRunnable(() =>
        {
            using (var toastClass = new AndroidJavaClass("android.widget.Toast"))
            {
                var toastObject = toastClass.CallStatic<AndroidJavaObject>("makeText", currentActivity, message, toastClass.GetStatic<int>("LENGTH_SHORT"));
                toastObject.Call("show");
            }
        }));
        #else
        Debug.Log("Toast: " + message); // Fallback cho Editor
        #endif
    }

    /// <summary>
    /// Hiển thị một Dialog thông báo với một nút 'OK'.
    /// </summary>
    public void ShowAlertDialog(string title, string message)
    {
        #if UNITY_ANDROID && !UNITY_EDITOR
        currentActivity.Call("runOnUiThread", new AndroidJavaRunnable(() =>
        {
            using (var builder = new AndroidJavaObject("android.app.AlertDialog$Builder", currentActivity))
            {
                builder.Call<AndroidJavaObject>("setTitle", title);
                builder.Call<AndroidJavaObject>("setMessage", message);
                builder.Call<AndroidJavaObject>("setPositiveButton", "OK", null);
                using(var dialog = builder.Call<AndroidJavaObject>("create"))
                {
                  dialog.Call("show");
                }
            }
        }));
        #else
        Debug.Log($"Alert: {title} - {message}"); // Fallback cho Editor
        #endif
    }

    // Ví dụ sử dụng từ Inspector hoặc gọi từ script khác
    public void OnTestButtonsClick()
    {
        ShowToast("Đây là một thông báo Toast!");
        ShowAlertDialog("Thông báo", "Bạn có muốn tiếp tục không?");
    }
}

