using UnityEngine;

public class AppLifecycleManager : MonoBehaviour
{
    // Hàm này được gọi khi ứng dụng mất hoặc có lại focus
    // isFocused = true: Người dùng quay trở lại app
    // isFocused = false: Người dùng chuyển sang app khác, mở thanh thông báo,...
    void OnApplicationFocus(bool isFocused)
    {
        if (!isFocused)
        {
            // Lưu game khi người dùng không còn tập trung vào app
            SaveGameData();
            Debug.Log("Application lost focus. Game saved.");
        }
    }

    // Hàm này được gọi khi ứng dụng bị tạm dừng (pause)
    // isPaused = true: App bị đưa xuống nền (nhấn nút Home), có cuộc gọi đến
    // isPaused = false: App được tiếp tục từ trạng thái pause
    void OnApplicationPause(bool isPaused)
    {
        if (isPaused)
        {
            // Tạm dừng game và lưu trạng thái
            Time.timeScale = 0; // Cẩn thận nếu game có logic dựa trên Coroutine
            SaveGameData();
            Debug.Log("Application is paused. Game saved.");
        }
        else
        {
            // Tiếp tục game
            Time.timeScale = 1;
            Debug.Log("Application is resumed.");
        }
    }

    // Hàm này được gọi ngay trước khi ứng dụng thoát hẳn
    // Hoạt động trên PC, Editor, và khi người dùng vuốt app khỏi recent apps trên mobile
    void OnApplicationQuit()
    {
        // Đảm bảo mọi dữ liệu quan trọng đều được lưu lại
        SaveGameData();
        Debug.Log("Application is quitting. Final save.");
    }

    private void SaveGameData()
    {
        // Đặt logic lưu game của bạn ở đây
        // Ví dụ: PlayerPrefs.SetInt("Score", 100); PlayerPrefs.Save();
        Debug.Log("Saving data...");
    }
}

